console.log("Loadhtml.js: Function running");const targetEl=document.querySelector(".target"),loadSnippet=t=>{fetch(`html${t}.html`).then((t=>{if(t.ok)return t.text()})).then((t=>{targetEl.innerHTML=t}))};window.onload=function(){setTimeout(document.querySelector(".eventsbutton").addEventListener(loadSnippet(1)),2e3),setTimeout(document.querySelector(".blogbutton").addEventListener(loadSnippet(2)),2e3),console.log("Loadhtml.js: Buttons loaded")};